'use strict';
const C=SalesCore,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n===null||n===undefined?'—':new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(n/100);
const baseText='item,unit_price\nApple,2.00\nOrange,3.00\nBanana,2.50\nCarrot,3.00\nBread,5.00\nMilk,4.00\nSoap,6.00\nDetergent,12.00\nCroissant,4.50';
const patchText='department,item,unit_price\nProduce,Carrot,2.50\nBakery,Bread,4.50';
let prices,patches,raw,rows=[],filename='',isDemo=true,pending=null,filter='All issues',search='',department='',mode='flagged',page=1;
function demoCSV(){const out=[['department','item','quantity','sale_total']];const specs=[['Grocery','Orange',3,9],['Produce','Carrot',2,5],['Household','Soap',2,12],['Bakery','Bread',2,9]];for(let i=0;i<232;i++){const [d,item,q,total]=specs[i%4];out.push([d,item,q,total.toFixed(2)]);}out.push(['Grocery','Orange',3,'7.00'],['Grocery','SKU-099',1,'8.00'],['Bakery','Bread',-2,'-9.00'],['Produce','Carrot',4,'11.00'],['Household','Detergent',2,'20.00'],['Produce','Kiwi',2,'4.00'],['Grocery','Milk',0,'0.00'],['Bakery','Croissant',3,'12.00']);return C.csv(out);}
function notify(message,error=false){$('#notice').hidden=false;$('#notice').className=error?'error':'';$('#notice').textContent=message;}
function resetDemo(){prices=C.priceList(C.parseCSV(baseText));patches=C.priceList(C.parseCSV(patchText),true);raw=C.parseCSV(demoCSV());rows=C.validate(raw,prices,patches);filename='November sales.csv';isDemo=true;pending=null;$('#sales-file').value='';$('#upload-selection').textContent='No file selected';$('#validate-btn').disabled=true;filter='All issues';search='';department='';mode='flagged';page=1;renderAll();}
function metric(label,value,foot,symbol,warn=false){return `<div class="metric ${warn?'warning':''}"><div class="metric-label">${label}<span class="metric-symbol">${symbol}</span></div><strong>${value}</strong><small>${foot}</small></div>`;}
function renderAll(){const s=C.summarize(rows);$('#file-name').textContent=filename;$('#file-detail').textContent=s.total.toLocaleString()+' transactions processed · checked against current prices';$('#data-badge').textContent=isDemo?'Demo data':'Your CSV';$('#nav-count').textContent=s.flagged;$('#metrics').innerHTML=metric('Valid sales',money(s.revenue),'<span class="mini-tag">AUD</span> &nbsp; From validated transactions','↗')+metric('Transactions',s.total.toLocaleString(),'Across '+s.departments.length+' departments','▤')+metric('Flagged records',s.flagged,'Ready for your review','△',true)+metric('Validation rate',s.rate.toFixed(1)+'%','Records passing all checks','◷');const max=Math.max(...s.departments.map(d=>d.revenue),1);const top=s.departments.slice(0,6);$('#department-chart').innerHTML=top.length?top.map(d=>`<div class="bar-group"><span class="bar-value">${money(d.revenue)}</span><div class="bar" style="height:${d.revenue/max*80}%" title="${esc(d.name)}: ${money(d.revenue)}"></div><span class="bar-label">${esc(d.name)}</span></div>`).join(''):'<div class="empty">Upload transactions to see department sales.</div>';$('#donut').style.background=`conic-gradient(var(--teal) ${s.rate}%,#edb378 0)`;$('#donut-value').textContent=s.rate.toFixed(1)+'%';$('#valid-count').textContent=s.valid;$('#flag-count').textContent=s.flagged;renderReview('#overview-review',true);renderReview('#full-results',false);$('#department-metrics').innerHTML=metric('Departments',s.departments.length,'Represented in the current file','▥')+metric('Valid sales',money(s.revenue),'Combined validated revenue','↗')+metric('Valid transactions',s.valid,'Passing all validation rules','✓')+metric('Flagged records',s.flagged,'Excluded from revenue','△',true);$('#department-table').innerHTML=table(['Department','Transactions','Valid','Flagged','Valid sales','Validation rate'],s.departments.map(d=>[esc(d.name),d.total,d.valid,d.flagged,money(d.revenue),(d.valid/d.total*100).toFixed(1)+'%']));renderPrices();}
function table(headers,data){return '<table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+data.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
function renderPrices(){$('#base-table').innerHTML=table(['Item','Unit price (AUD)'],[...prices].map(([k,v])=>[esc(k),money(v)]));$('#patch-table').innerHTML=patches.size?table(['Department','Item','Unit price'],[...patches].map(([k,v])=>{const [d,item]=JSON.parse(k);return [esc(d),esc(item),money(v)];})):'<div class="empty">No department overrides. Base prices apply.</div>';}
const issues=['All issues','Price mismatch','Unknown item','Invalid quantity','Invalid amount','Missing field','Amount too large'];
function selectedRows(overview=false){return rows.filter(r=>(overview||mode==='flagged'?!r.valid:true)&&(filter==='All issues'||r.issue===filter)&&(!department||r.department===department)&&(!search||(r.item+' '+r.department+' '+r.issue).toLowerCase().includes(search.toLowerCase())));}
function renderReview(target,overview){const el=$(target),list=overview?rows.filter(r=>!r.valid):selectedRows();const size=overview?4:12;const totalPages=Math.max(1,Math.ceil(list.length/size));if(!overview)page=Math.min(page,totalPages);const start=overview?0:(page-1)*size;const shown=list.slice(start,start+size);const heading=overview?'Transactions requiring review':'Transaction explorer';el.innerHTML=`<div class="card-heading"><div><h2>${heading}</h2><p>${overview?'A closer look at the records that need attention.':'Inspect the recorded amount, expected total, and reason for each result.'}</p></div>${overview?'<a href="#results" class="small-link">View all results ↗</a>':'<div class="tab-toggle"><button class="chip '+(mode==='flagged'?'active':'')+'" data-mode="flagged">Flagged</button><button class="chip '+(mode==='all'?'active':'')+'" data-mode="all">All transactions</button></div>'}</div>${overview?'':`<div class="table-toolbar">${issues.filter((x,i)=>i===0||rows.some(r=>r.issue===x)).map(x=>`<button class="chip ${filter===x?'active':''}" data-filter="${x}">${x}${x==='All issues'?' · '+rows.filter(r=>!r.valid).length:''}</button>`).join('')}<div class="toolbar-end"><input class="search" type="search" aria-label="Search transactions" placeholder="Search item or department" value="${esc(search)}"><select class="department-filter" aria-label="Filter department"><option value="">All departments</option>${[...new Set(rows.map(r=>r.department))].filter(Boolean).sort().map(d=>`<option ${department===d?'selected':''} value="${esc(d)}">${esc(d)}</option>`).join('')}</select></div></div>`}<div class="table-scroll">${shown.length?table(['Row','Department','Item','Qty','Recorded','Expected','Result'],shown.map(r=>[r.row,esc(r.department)||'—',esc(r.item)||'—',esc(r.quantity),money(r.recorded),money(r.expected),`<span class="status ${r.valid?'valid':''}">${r.valid?'✓ Valid':'△ '+esc(r.issue)}</span>${r.valid&&r.override?'<small class="subtext">Department price applied</small>':''}${r.issue==='Price mismatch'?'<small class="subtext">Difference: '+money(r.recorded-r.expected)+'</small>':''}`])):`<div class="empty">${rows.some(r=>!r.valid)?'No transactions match these filters.':'✓ All transactions passed validation.'}</div>`}</div><div class="card-footer"><button class="text-button download-flagged">↓ Download flagged rows CSV</button>${overview?`<span>Showing ${shown.length} of ${list.length} flagged records</span>`:`<div class="pagination"><span>${list.length?start+1:0}–${Math.min(start+size,list.length)} of ${list.length}</span><button class="text-button prev" ${page<=1?'disabled':''}>←</button><span>${page} / ${totalPages}</span><button class="text-button next" ${page>=totalPages?'disabled':''}>→</button></div>`}</div>`;
 el.querySelector('.download-flagged').onclick=()=>exportRows(rows.filter(r=>!r.valid),'salescheck-flagged.csv');if(overview)return;el.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;page=1;renderReview(target,false);});el.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;filter='All issues';page=1;renderReview(target,false);});el.querySelector('.department-filter').onchange=e=>{department=e.target.value;page=1;renderReview(target,false);};el.querySelector('.search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;page=1;renderReview(target,false);const input=el.querySelector('.search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}};el.querySelector('.prev').onclick=()=>{page--;renderReview(target,false);};el.querySelector('.next').onclick=()=>{page++;renderReview(target,false);};}
function download(name,text){const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportRows(data,name){download(name,C.csv([['row','department','item','quantity','recorded','expected','difference','status','price_source'],...data.map(r=>[r.row,r.department,r.item,r.quantity,r.recorded===null?r.sale_total:(r.recorded/100).toFixed(2),r.expected===null?'':(r.expected/100).toFixed(2),r.expected!==null&&r.recorded!==null?((r.recorded-r.expected)/100).toFixed(2):'',r.valid?'Valid':r.issue,r.override?'Department override':'Base price'])]));notify('Downloaded '+name+'.');}
async function readFile(file){if(!file)throw Error('Choose a CSV first.');if(!/\.csv$/i.test(file.name))throw Error('Please choose a .csv file.');if(file.size>5*1024*1024)throw Error('This file exceeds 5 MB. Please split it into smaller files.');const parsed=C.parseCSV(await file.text());if(parsed.rows.length>20000)throw Error('This file exceeds 20,000 records. Please split it into smaller files.');return parsed;}
async function selectFile(file){pending=null;$('#validate-btn').disabled=true;try{const parsed=await readFile(file);C.requireColumns(parsed,['department','item','quantity','sale_total']);pending={parsed,name:file.name};$('#upload-selection').textContent=file.name+' · '+parsed.rows.length+' records ready';$('#validate-btn').disabled=false;$('#notice').hidden=true;}catch(e){$('#upload-selection').textContent='File could not be loaded';notify(e.message,true);}}
$('#sales-file').onchange=e=>selectFile(e.target.files[0]);const dz=$('#dropzone');dz.addEventListener('dragover',e=>{e.preventDefault();dz.classList.add('drag');});dz.addEventListener('dragleave',()=>dz.classList.remove('drag'));dz.addEventListener('drop',e=>{e.preventDefault();dz.classList.remove('drag');selectFile(e.dataTransfer.files[0]);});
$('#validate-btn').onclick=()=>{if(!pending)return;try{const result=C.validate(pending.parsed,prices,patches);C.summarize(result);raw=pending.parsed;rows=result;filename=pending.name;isDemo=false;filter='All issues';search='';department='';page=1;renderAll();location.hash='overview';notify('Validation complete. '+rows.filter(r=>!r.valid).length+' of '+rows.length+' records need review.');}catch(e){notify(e.message,true);}};
for(const [id,override] of [['base-file',false],['patch-file',true]]){$('#'+id).onchange=async e=>{try{const p=await readFile(e.target.files[0]);const next=C.priceList(p,override);const newRows=C.validate(raw,override?prices:next,override?next:patches);C.summarize(newRows);if(override)patches=next;else prices=next;rows=newRows;page=1;renderAll();notify('Price list replaced. Current sales have been revalidated.');}catch(err){notify(err.message,true);}finally{e.target.value='';}};}
$('#export-btn').onclick=()=>exportRows(rows,'salescheck-report.csv');$('#reset-demo').onclick=()=>{if(!isDemo&&!confirm('Replace your current sales and price lists with demo data?'))return;resetDemo();notify('Demo sales and price lists restored.');};$('#sample-btn').onclick=()=>download('salescheck-sample.csv',demoCSV());$('#base-template').onclick=()=>download('salescheck-base-prices.csv',C.csv([['item','unit_price'],...[...prices].map(([k,v])=>[k,(v/100).toFixed(2)])]));$('#patch-template').onclick=()=>download('salescheck-department-prices.csv',C.csv([['department','item','unit_price'],...[...patches].map(([k,v])=>[...JSON.parse(k),(v/100).toFixed(2)])]));$('#department-export').onclick=()=>{const s=C.summarize(rows);download('salescheck-departments.csv',C.csv([['department','transactions','valid','flagged','valid_sales','validation_rate'],...s.departments.map(d=>[d.name,d.total,d.valid,d.flagged,(d.revenue/100).toFixed(2),(d.valid/d.total*100).toFixed(1)+'%'])]));notify('Department report downloaded.');};
$('#rules-btn').onclick=()=>$('#rules-dialog').showModal();$('.dialog-close').onclick=()=>$('#rules-dialog').close();$('#rules-dialog').onclick=e=>{if(e.target===$('#rules-dialog'))$('#rules-dialog').close();};
const pages={overview:['Overview','Sales overview','Your numbers, checked. Your next steps, clear.'],upload:['Upload data','Start with your data','A quick upload. A clearer picture of every transaction.'],results:['Validation results','Every detail, accounted for','Find the discrepancy. Understand the difference.'],departments:['Department reports','One business. Every department.','See how each department contributes to your validated sales.'],prices:['Price lists','The right price, every time','Define your base prices and department-specific exceptions.']};
function route(){let key=location.hash.slice(1)||'overview';if(!pages[key])key='overview';const [crumb,title,sub]=pages[key];$('#breadcrumb').textContent=crumb;$('#page-title').textContent=title;$('#page-subtitle').textContent=sub;document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!=='page-'+key);document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===key);if(a.dataset.page===key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=crumb+' · SalesCheck';}window.addEventListener('hashchange',route);resetDemo();route();
